package org.jsoup.select;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.parser.TokenQueue;
import org.jsoup.select.Evaluator;
import org.jsoup.select.QueryParser;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertThrows;

public class QueryParser_parse_TriageGen2Test {

    @Test
    public void testParse_EmptyQuery() {
        QueryParser p = new QueryParser("");
        Evaluator result = p.parse();
        assertEquals(new Evaluator(), result);
    }

    @Test
    public void testParse_NullQuery() {
        QueryParser p = new QueryParser(null);
        assertThrows(NullPointerException.class, () -> p.parse());
    }

    @Test
    public void testParse_QueryWithSelector() {
        QueryParser p = new QueryParser("div");
        Evaluator result = p.parse();
        assertEquals(new Evaluator("div"), result);
    }

    @Test
    public void testParse_QueryWithSelectorAndAttribute() {
        QueryParser p = new QueryParser("div[id]");
        Evaluator result = p.parse();
        assertEquals(new Evaluator("div", "id"), result);
    }

    @Test
    public void testParse_QueryWithSelectorAndAttributeAndValue() {
        QueryParser p = new QueryParser("div[id='test']");
        Evaluator result = p.parse();
        assertEquals(new Evaluator("div", "id", "test"), result);
    }

    @Test
    public void testParse_QueryWithMultipleSelectors() {
        QueryParser p = new QueryParser("div, span");
        Evaluator result = p.parse();
        assertEquals(new Evaluator("div, span"), result);
    }

    @Test
    public void testParse_QueryWithMultipleSelectorsAndAttributes() {
        QueryParser p = new QueryParser("div[id], span[id]");
        Evaluator result = p.parse();
        assertEquals(new Evaluator("div[id], span[id]"), result);
    }

    @Test
    public void testParse_QueryWithMultipleSelectorsAndAttributesAndValues() {
        QueryParser p = new QueryParser("div[id='test'], span[id='test']");
        Evaluator result = p.parse();
        assertEquals(new Evaluator("div[id='test'], span[id='test']"), result);
    }
}
